16:   base64ToArrayBuffer(base64: string): ArrayBuffer {
17:     const binaryString = window.atob(base64);
18:     const len = binaryString.length;
19:     const bytes = new Uint8Array(len);
20:     for (let i = 0; i < len; i++) {
21:       bytes[i] = binaryString.charCodeAt(i);
22:     }
23:     return bytes.buffer;
